def authorize(principal, tenant, role):
    if not isinstance(principal, dict):
        return False
    if not isinstance(tenant, str) or not tenant.strip():
        return False
    if not isinstance(role, str) or not role.strip():
        return False
    principal_tenant = principal.get("tenant")
    roles = principal.get("roles")
    if not isinstance(principal_tenant, str) or not principal_tenant.strip():
        return False
    if not isinstance(roles, list) or any(
        not isinstance(item, str) or not item.strip() for item in roles
    ):
        return False
    return principal_tenant == tenant and (role in roles or "admin" in roles)
